import{z as B,x as m,o as l,c as A,q as o,j as i,D as t,d as r,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"CRRA 组合选择","description":"","frontmatter":{"title":"CRRA 组合选择","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/crra-portfolio-choice.md","filePath":"quant/crra-portfolio-choice.md","lastUpdated":1791413859000}'),p={name:"quant/crra-portfolio-choice.md"};function C(d,a,f,u,D,c){const E=m("Mermaid");return l(),A("div",null,[a[2]||(a[2]=o('<h1 id="crra-组合选择" tabindex="-1">CRRA 组合选择 <a class="header-anchor" href="#crra-组合选择" aria-label="Permalink to &quot;CRRA 组合选择&quot;">​</a></h1><div class="epigraph"><p>风险厌恶不是一句「保守」，是一个数：CRRA 效用里它叫 γ——γ 一变，最优仓位、杠杆与生命周期储蓄全跟着改写。</p><footer>—— 据 Merton (1971) 连续时间组合选择；Campbell–Viceira《Strategic Asset Allocation》</footer></div><p><a href="/quant/kupiec-backtest">Kupiec 回测</a>检验的是模型输出，本课回到选择的原点：给定收益分布，投资者该持多少风险资产。缺口是<strong>效用函数的具体形状</strong>——CRRA（常相对风险厌恶）是资产配置的默认语言，\\(\\gamma\\) 是其中唯一旋钮。本课只做单期与连续时间同分布情形，不做时变预期收益。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最大化期望财富会全押高风险资产（期望更高），最大化对数财富又过于削峰——哪个对？缺一个既平滑又可标定的目标函数。CRRA \\(u(W)=W^{1-\\gamma}/(1-\\gamma)\\) 给出：相对风险厌恶恒为 \\(\\gamma\\)，行为不随财富规模改变。问题拆两问：\\(\\gamma\\) 取多少合理？给定 \\(\\gamma\\)，最优风险权重是多少？</p><p><span class="marginnote">术语翻译：相对风险厌恶 \\(RRA=-W u&#39;&#39;/u&#39;\\)——「对财富百分比波动的厌恶」；CRRA 即它为常数。γ=1 时退化为对数效用；γ→∞ 是无限保守。</span></p><p><span class="marginnote">数字实例：50/50 抛硬币 ±20% 是公平赌局——对数投资者最优杠杆 \\(f=2p-1=0\\)，\\(\\gamma=3\\) 同样是零：风险厌恶者的入场券必须是正期望。补上 \\(+6\\%\\) 超额期望（\\(\\sigma=20\\%\\)）后，拇指法则给 \\(f=0.06/(3\\times0.04)=50\\%\\)——同一个投资者，期望一变仓位立变。期望财富最大化者则无论公平与否全押，长期中位数财富趋零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单期解两步：写出 \\(EU=u(W_0(1+r_f+f(r_e-r_f)))\\)；对 \\(f\\) 求一阶条件。收益小时用泰勒展开得拇指法则 \\(f^\\*\\approx(\\mu-r_f)/(\\gamma\\sigma^2)\\)——超额收益除以「γ 乘方差」。连续时间 Merton 解同形：\\(\\pi^\\*=(\\mu-r)/(\\gamma\\sigma^2)\\)，无劳动收入、常数机会集下权重是常数，再平衡就是让它保持常数。</p>',9)),(l(),i(s,null,{default:t(()=>[n(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%95%88%E7%94%A8%3A%20W%5E(1-%CE%B3)%2F(1-%CE%B3)%22%5D%20--%3E%20B%5B%22%E5%AF%B9%E9%A3%8E%E9%99%A9%E6%9D%83%E9%87%8D%20f%20%E6%B1%82%E4%B8%80%E9%98%B6%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%B0%8F%E6%94%B6%E7%9B%8A%E8%BF%91%E4%BC%BC%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8B%87%E6%8C%87%E6%B3%95%E5%88%99%20f*%20%3D%20%CE%BC-r%20%2F%20%CE%B3%CF%83%C2%B2%22%5D%0A%20%20D%20--%3E%20E%7B%22%CE%B3%20%3D%20%3F%22%7D%0A%20%20E%20--%3E%7C%22%CE%B3%3D1%22%7C%20F%5B%22%E5%AF%B9%E6%95%B0%3A%20f%3D%CE%BC-r%2F%CF%83%C2%B2%22%5D%0A%20%20E%20--%3E%7C%22%CE%B3%3D3%22%7C%20G%5B%22%E4%BB%93%E4%BD%8D%E7%BC%A9%E5%88%B0%201%2F3%22%5D%0A%20%20E%20--%3E%7C%22%CE%B3%E2%86%92%E2%88%9E%22%7C%20H%5B%22%E8%B6%8B%E8%BF%91%E6%97%A0%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：γ 像汽车的避震硬度——γ=1 是跑车悬架，颠簸全受、吃满速度；γ=6 是越野悬架，稳但慢。Merton 公式说「油门开度 = 路况奖励 ÷（避震硬度 × 颠簸方差）」，硬度调一倍，油门就得松一半。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[r("CRRA 的两个解析福利：一是"),e("strong",null,"同质性"),r("——财富翻倍最优仓位百分比不变，适合跨投资者比较；二是"),e("strong",null,"闭式路径"),r("——连乘 \\(W_T=W_0\\prod(1+r_f+f r_i)\\) 取对数后是独立同分布之和，大数定律保证长期增长率 \\(\\ln W\\) 收敛于 \\(E[\\ln(1+r_f+f r)]\\)，最优 \\(f\\) 就是最大化这个增长率——这正是 Kelly 准则与 γ=1 的重合点。Merton 公式的标定误差也摆在明处（若 \\(\\mu-r=6\\%\\)、\\(\\sigma=20\\%\\)、γ=3，则 \\(f=0.06/(3\\times0.04)=50\\%\\)）：仓位 \\(\\propto1/(\\gamma\\sigma^2)\\)，σ 从 20% 估到 21%，仓位就缩约 9%——对平方项的敏感度要有肌肉记忆。")],-1)),(l(),i(s,null,{default:t(()=>[n(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%95%BF%E6%9C%9F%E4%B8%AD%E8%B0%81%E8%B5%A2%3F%22%5D%20--%3E%20R%5B%22ln%20W%20%3D%20%CE%A3%20ln(1%2Br)%22%5D%0A%20%20R%20--%3E%20S%5B%22%E5%A4%A7%E6%95%B0%E5%AE%9A%E5%BE%8B%3A%20%E5%A2%9E%E9%95%BF%E7%8E%87%20%E2%86%92%20E%20ln%22%5D%0A%20%20S%20--%3E%20T%5B%22%CE%B3%3D1%3A%20%E6%9C%80%E5%A4%A7%E5%8C%96%20E%20ln%20%3D%20Kelly%22%5D%0A%20%20U%5B%22%CE%B3%20%E2%89%A0%201%22%5D%20--%3E%20V%5B%22Merton%20%E6%9D%83%E9%87%8D%20%3D%20%CE%BC-r%20%2F%20%CE%B3%CF%83%C2%B2%22%5D%0A%20%20T%20--%3E%20W%5B%22%E4%B8%A4%E6%97%8F%E8%A7%A3%E5%9C%A8%20%CE%B3%3D1%20%E7%9B%B8%E4%BA%A4%22%5D%0A%20%20V%20--%3E%20W%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：把问卷风险得分直接当 γ——「能承受 20% 回撤」翻译成 γ 需要经过收益分布假设，同一句话在 σ=10% 与 σ=25% 的世界里 γ 差 6 倍；另一误区是 γ 全资产共用——人力资本是隐性债券，年轻投资者的有效 γ 对金融资产要折价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CRRA 假设偏好不随财富改变，行为金融的损失厌恶（前景理论）直接拒绝这一点；时变机会集下最优仓位应随预期收益漂移，常数 \\(\\pi^\\*\\) 只在 IID 世界成立。γ 的实证区间 1–10 跨一个数量级，资产配置对它一次幂敏感——报出仓位时同时报出 γ 与 σ 的标定来源是职业规范。本课与 <a href="/quant/kelly-sizing">Kelly 准则</a>、<a href="/quant/risk-budgeting">风险预算</a>的关系：Kelly 是 γ=1 的特例，风险预算是把 γ 换成「各资产风险贡献相等」的另一族解——三家是同一枚硬币的三种面。</p><p><span class="marginnote">直觉类比：γ、Kelly、风险预算像同一台调音台的三个推子——Kelly 按增长率推满，风险预算按各声部均衡推平，CRRA 按客户的耳朵（偏好）推；音乐不同，电路是同一套。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CRRA 用一个 γ 概括风险厌恶；Merton 权重 \\(\\pi^\\*=(\\mu-r)/(\\gamma\\sigma^2)\\)。</li><li>γ=1 退化为 Kelly——增长率最大化是效用族的特例而非对立面。</li><li>标定诚实：报仓位必须同时报 γ 与 σ 的来源，否则不可复核。</li><li>出处：Merton「Optimum Consumption and Portfolio Rules」1971；Campbell–Viceira 2002；Kelly 1956。</li></ul>',6))])}const h=B(p,[["render",C]]);export{_ as __pageData,h as default};
